import java.util.*;

class Solution {
    public int minimumEffortPath(int[][] heights) {
        int m = heights.length, n = heights[0].length;
        int[][] effort = new int[m][n];
        for (int[] row : effort) Arrays.fill(row, Integer.MAX_VALUE);
        effort[0][0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, 0, 0});
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int e = cur[0], i = cur[1], j = cur[2];
            if (i == m - 1 && j == n - 1) return e;
            if (e > effort[i][j]) continue;
            for (int[] d : dirs) {
                int ni = i + d[0], nj = j + d[1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                    int newEffort = Math.max(e, Math.abs(heights[ni][nj] - heights[i][j]));
                    if (newEffort < effort[ni][nj]) {
                        effort[ni][nj] = newEffort;
                        pq.offer(new int[]{newEffort, ni, nj});
                    }
                }
            }
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int minimumEffortPath(int[][] heights) {
        int m = heights.length, n = heights[0].length;
        int lo = 0, hi = 1000000;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (canReach(heights, m, n, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean canReach(int[][] heights, int m, int n, int maxEffort) {
        boolean[][] visited = new boolean[m][n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0});
        visited[0][0] = true;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int i = cur[0], j = cur[1];
            if (i == m - 1 && j == n - 1) return true;
            for (int[] d : dirs) {
                int ni = i + d[0], nj = j + d[1];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && !visited[ni][nj]) {
                    if (Math.abs(heights[ni][nj] - heights[i][j]) <= maxEffort) {
                        visited[ni][nj] = true;
                        queue.offer(new int[]{ni, nj});
                    }
                }
            }
        }
        return false;
    }
}
